import java.util.*;

public class Main {
    static int createSortedArray(int[] instructions) {
        long MOD = 1_000_000_007L, cost = 0;
        List<Integer> sorted = new ArrayList<>();
        for (int x : instructions) {
            int less = lowerBound(sorted, x);
            int greater = sorted.size() - upperBound(sorted, x);
            cost += Math.min(less, greater);
            sorted.add(less, x);                             // O(n) shift
        }
        return (int) (cost % MOD);
    }
    static int lowerBound(List<Integer> a, int x) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int mid = (lo + hi) / 2; if (a.get(mid) < x) lo = mid + 1; else hi = mid; }
        return lo;
    }
    static int upperBound(List<Integer> a, int x) {
        int lo = 0, hi = a.size();
        while (lo < hi) { int mid = (lo + hi) / 2; if (a.get(mid) <= x) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

