    for (int x : instructions) {
        int less = lower_bound(sorted_list.begin(), sorted_list.end(), x) - sorted_list.begin();
        int greater = sorted_list.end() - upper_bound(sorted_list.begin(), sorted_list.end(), x);
        cost += min(less, greater);
        sorted_list.insert(sorted_list.begin() + less, x);   // O(n) shift
    }
    return cost % MOD;
